CREATE TABLE ad_packages (id UUID PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description TEXT, price NUMERIC(15,2) NOT NULL CHECK(price >= 0), duration_days INT NOT NULL CHECK(duration_days > 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ad_campaigns (id UUID PRIMARY KEY, organizer_id UUID NOT NULL, package_id UUID NOT NULL REFERENCES ad_packages(id), name VARCHAR(150) NOT NULL, pricing_mode VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, rejection_reason TEXT, fee_amount NUMERIC(15,2) NOT NULL DEFAULT 0, escrow_amount NUMERIC(15,2) NOT NULL DEFAULT 0, settlement_published BOOLEAN NOT NULL DEFAULT FALSE, starts_at TIMESTAMP NOT NULL, ends_at TIMESTAMP NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(ends_at > starts_at));
CREATE TABLE banners (id UUID PRIMARY KEY, campaign_id UUID NOT NULL REFERENCES ad_campaigns(id), image_url VARCHAR(1000) NOT NULL, pending_image_url VARCHAR(1000), position VARCHAR(30) NOT NULL, priority INT NOT NULL DEFAULT 0, starts_at TIMESTAMP NOT NULL, ends_at TIMESTAMP NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(ends_at > starts_at));
CREATE INDEX idx_campaign_organizer ON ad_campaigns(organizer_id, status); CREATE INDEX idx_banner_public ON banners(active, position, priority DESC, starts_at, ends_at); CREATE INDEX idx_banner_campaign ON banners(campaign_id);
